import React, { useState } from "react";
import "../styles/SkinAnalyzer.css";

export default function SkinAnalyzer() {
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [recommendations, setRecommendations] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingRec, setLoadingRec] = useState(false);

  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setPhoto(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const analyzeSkin = async () => {
    if (!photo) {
      alert("Загрузите фото!");
      return;
    }

    setLoading(true);
    setAnalysis(null);
    setRecommendations("");

    const formData = new FormData();
    formData.append("photo", photo);

    try {
      const res = await fetch("http://localhost:4000/api/skin/analyze", {
        method: "POST",
        credentials: "include",
        body: formData,
      });

      const data = await res.json();
      setAnalysis(data);
    } catch (err) {
      console.error(err);
      alert("Ошибка анализа кожи");
    }

    setLoading(false);
  };

  const getRecommendations = async () => {
    if (!analysis) {
      alert("Сначала сделайте анализ!");
      return;
    }

    setLoadingRec(true);

    try {
      const res = await fetch("http://localhost:4000/api/skin/recommend", {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ skinAnalysis: analysis }),
      });

      const data = await res.json();
      setRecommendations(data.recommendations);
    } catch (err) {
      console.error(err);
      alert("Ошибка получения рекомендаций");
    }

    setLoadingRec(false);
  };

  // Функция для форматирования процентов с цветами
  const getPercentageColor = (percent) => {
    const num = parseFloat(percent);
    if (num > 70) return "var(--danger)";
    if (num > 40) return "var(--warning)";
    return "var(--success)";
  };

  // Функция для форматирования текста рекомендаций
  const formatRecommendations = (text) => {
    if (!text) return [];

    // Разделяем на абзацы по двойным переносам строк
    const paragraphs = text.split('\n\n').filter(p => p.trim());
    return paragraphs;
  };

  // Функция для форматирования строки рекомендации
  const formatRecommendationLine = (line, isBold = false) => {
    // Убираем маркеры списка
    const cleanLine = line
      .replace(/^\d+\.\s/, '')
      .replace(/^[-•]\s/, '')
      .trim();

    // Добавляем жирный текст для заголовков
    if (isBold || line.includes('**') || line.match(/^[А-Я].*:/)) {
      return <strong>{cleanLine.replace(/\*\*/g, '')}</strong>;
    }

    // Форматируем жирный текст внутри строки
    const parts = cleanLine.split(/\*\*/);
    return parts.map((part, index) => {
      if (index % 2 === 1) {
        return <strong key={index}>{part}</strong>;
      }
      return part;
    });
  };

  // Функция для определения типа абзаца
  const getParagraphType = (paragraph) => {
    const firstLine = paragraph.split('\n')[0];
    if (firstLine.includes('Судя по') || firstLine.includes('**')) {
      return 'intro';
    }
    if (firstLine.includes('Рекомендации')) {
      return 'title';
    }
    if (paragraph.includes('1.') || paragraph.includes('2.') || paragraph.includes('3.')) {
      return 'list';
    }
    return 'regular';
  };

  return (
    <div className="skin-analyzer">
      <div className="container">
        <h2 className="title">🧬 Анализ кожи</h2>

        {/* Загрузка фото */}
        <div className="upload-section">
          <div className="file-input-container">
            <label className="file-input-label">
              <input 
                type="file" 
                accept="image/*" 
                onChange={handlePhotoChange} 
                className="file-input"
              />
              <span className="upload-button">
                📸 Выбрать фото
              </span>
            </label>
            {photo && (
              <span className="file-name">
                {photo.name}
              </span>
            )}
          </div>

          {photoPreview && (
            <div className="photo-preview">
              <img src={photoPreview} alt="Предпросмотр" />
            </div>
          )}

          <button 
            onClick={analyzeSkin} 
            disabled={loading || !photo}
            className="analyze-button"
          >
            {loading ? (
              <>
                <span className="spinner"></span>
                Анализируем...
              </>
            ) : "🔍 Анализировать кожу"}
          </button>
        </div>

        {/* Результаты анализа */}
        {analysis && (
          <div className="results-section">
            <h3 className="section-title">
              📊 Результат анализа
              {analysis.summary && (
                <span className="confidence-badge">
                  Достоверность: {analysis.summary.confidence}%
                </span>
              )}
            </h3>

            <div className="analysis-grid">
              {analysis.analysis && analysis.analysis.formatted ? (
                analysis.analysis.formatted.map((item, index) => (
                  <div key={index} className="analysis-item">
                    <div className="analysis-header">
                      <span className="item-index">#{index + 1}</span>
                      <span className="item-name">{item.name}</span>
                    </div>
                    <div className="progress-container">
                      <div className="progress-bar">
                        <div 
                          className="progress-fill"
                          style={{
                            width: `${item.percentage || (item.value * 100)}%`,
                            backgroundColor: getPercentageColor(item.percentage || (item.value * 100))
                          }}
                        ></div>
                      </div>
                      <span 
                        className="percentage"
                        style={{ color: getPercentageColor(item.percentage || (item.value * 100)) }}
                      >
                        {item.percentage || (item.value * 100).toFixed(1)}%
                      </span>
                    </div>
                    <div className="item-level">
                      {item.level || (
                        item.value > 0.7 ? "🔴 Высокая вероятность" :
                        item.value > 0.4 ? "🟡 Средняя вероятность" : 
                        "🟢 Низкая вероятность"
                      )}
                    </div>
                  </div>
                ))
              ) : (
                // Старый формат
                analysis.formatted.split('\n').map((line, index) => {
                  const match = line.match(/(.+?) — (\d+\.?\d*)%/);
                  if (match) {
                    const [, name, percent] = match;
                    return (
                      <div key={index} className="analysis-item">
                        <div className="analysis-header">
                          <span className="item-index">#{index + 1}</span>
                          <span className="item-name">{name.trim()}</span>
                        </div>
                        <div className="progress-container">
                          <div className="progress-bar">
                            <div 
                              className="progress-fill"
                              style={{
                                width: `${percent}%`,
                                backgroundColor: getPercentageColor(percent)
                              }}
                            ></div>
                          </div>
                          <span 
                            className="percentage"
                            style={{ color: getPercentageColor(percent) }}
                          >
                            {percent}%
                          </span>
                        </div>
                      </div>
                    );
                  }
                  return null;
                }).filter(Boolean)
              )}
            </div>

            <button 
              onClick={getRecommendations} 
              disabled={loadingRec}
              className="recommend-button"
            >
              {loadingRec ? (
                <>
                  <span className="spinner"></span>
                  Генерируем рекомендации...
                </>
              ) : "💡 Получить рекомендации по уходу"}
            </button>
          </div>
        )}

        {/* Рекомендации */}
        {recommendations && (
          <div className="recommendations-section">
            <h3 className="section-title">🌟 Рекомендации по уходу</h3>

            <div className="recommendations-card">
              <div className="recommendations-content">
                {formatRecommendations(recommendations).map((paragraph, paraIndex) => {
                  const type = getParagraphType(paragraph);
                  const lines = paragraph.split('\n').filter(line => line.trim());

                  return (
                    <div 
                      key={paraIndex} 
                      className={`recommendation-paragraph ${type}`}
                    >
                      {lines.map((line, lineIndex) => {
                        const isListItem = line.match(/^\d+\.\s/);
                        const isBold = type === 'title' || type === 'intro' || line.includes('**');

                        return (
                          <div 
                            key={lineIndex} 
                            className={`rec-line ${isListItem ? 'list-item' : ''}`}
                          >
                            {isListItem && (
                              <div className="list-marker">
                                <span className="list-number">
                                  {line.match(/^\d+/)[0]}
                                </span>
                              </div>
                            )}
                            <div className="rec-text">
                              {formatRecommendationLine(line, isBold)}
                            </div>
                          </div>
                        );
                      })}
                      {paraIndex < formatRecommendations(recommendations).length - 1 && (
                        <div className="paragraph-spacer" />
                      )}
                    </div>
                  );
                })}
              </div>

              <div className="recommendations-footer">
                <div className="tip">
                  💡 Важно: Данные рекомендации являются информационными. Для точной диагностики обратитесь к специалисту.
                </div>
                <button 
                  className="save-button"
                  onClick={() => {
                    navigator.clipboard.writeText(recommendations);
                    alert("Рекомендации скопированы в буфер обмена!");
                  }}
                >
                  📋 Скопировать рекомендации
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
